class C {
  fun run(): Int {
    var sum = 0
    var i = 0
    while (i < 10) {
      i = i + 1
      if (i == 3) { continue }
      if (i == 6) { break }
      sum = sum + i
    }
    var j = 0
    do {
      sum = sum + 10
      j = j + 1
    } while (j < 3)
    when (j) {
      3 -> { sum = sum + 100 }
      else -> { sum = sum + 1 }
    }
    return sum
  }
}
